const fs = require('node:fs');
const crypto = require('node:crypto');
const base = 'products/distribution/catalogue-referral/';
const homepage = fs.readFileSync(base + '2026-11-18-live-destination.html');
const savedPath = JSON.parse(fs.readFileSync(base + 'saved-inquiry-path.json', 'utf8'));
const handoff = fs.readFileSync(base + 'operator-handoff.md', 'utf8');
const contract = fs.readFileSync('docs/AGENTMAIL.md', 'utf8');
const html = homepage.toString('utf8');
const excerpt = /plain.text|anonym|syntheti|confiden|20 rows|20 lignes|hypoth|CAD|verify|input.only|produced rows/i;
const lines = html.split(/\r?\n/).filter(line => excerpt.test(line)).map(line => line.replace(/mailto:[^"'\s<>]+/gi, 'mailto:[redacted]').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim()).filter(Boolean);
const contractLines = contract.split(/\r?\n/).filter(line => /case.local|attachment|inline|UTF-8|offline|incoming|recipient/i.test(line)).map(line => line.replace(/[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/g, '[redacted]')).slice(0, 24);
const report = {scope: 'Offline source excerpts for the fictional buyer walkthrough. No inquiry sent and no private cycle exercised.', liveCaptureSha256: crypto.createHash('sha256').update(homepage).digest('hex'), inquiryPathEvidenceFields: Object.keys(savedPath), publishedScopeExcerpts: lines.slice(0, 28), privateCycleContractExcerpts: contractLines, handoffSha256: crypto.createHash('sha256').update(handoff).digest('hex')};
if (!report.publishedScopeExcerpts.length || !contractLines.length) throw new Error('Source excerpts missing');
const output = 'products/distribution/catalogue-buyer-request-path/source-check.json';
fs.mkdirSync(require('node:path').dirname(output), {recursive: true});
fs.writeFileSync(output, JSON.stringify(report, null, 2) + '\n');
